/*
 * Analyze Rain Risk - V2
 * Weather Alert Bot - Multi Location
 *
 * Business Rules:
 * NONE     = 0%
 * LOW      = 1-29%
 * MODERATE = 30-59%
 * WATCH    = 60-69%
 * HIGH     = 70-100%
 *
 * Important:
 * riskHours contains WATCH and HIGH only.
 * MODERATE is stored separately for Daily Summary.
 */

// ==========================================
// 1. Get Input
// ==========================================

const items = $input.all();

if (items.length === 0) {
  throw new Error("No weather data received");
}

// ==========================================
// 2. Define Risk Thresholds
// ==========================================

const MODERATE_THRESHOLD = 30;
const WATCH_THRESHOLD = 60;
const HIGH_THRESHOLD = 70;

// ==========================================
// 3. Classify Rain Probability
// ==========================================

function classifyRisk(probability) {

  if (probability === 0) {
    return "NONE";
  }

  if (probability < MODERATE_THRESHOLD) {
    return "LOW";
  }

  if (probability < WATCH_THRESHOLD) {
    return "MODERATE";
  }

  if (probability < HIGH_THRESHOLD) {
    return "WATCH";
  }

  return "HIGH";
}

// ==========================================
// 4. Process Each Location
// ==========================================

return items.map((item, index) => {

  const data = item.json;

  // ----------------------------------------
  // 4.1 Validate Location
  // ----------------------------------------

  if (!data.locationId || !data.locationName) {
    throw new Error(
      `Missing location information at item ${index}`
    );
  }

  // ----------------------------------------
  // 4.2 Validate Forecast
  // ----------------------------------------

  if (
    !Array.isArray(data.forecast) ||
    data.forecast.length === 0
  ) {
    throw new Error(
      `Missing forecast data for ${data.locationName}`
    );
  }

  // ----------------------------------------
  // 4.3 Classify Every Forecast Hour
  // ----------------------------------------

  const classifiedForecast = data.forecast.map(hour => {

    if (
      !hour.time ||
      hour.rainProbability === null ||
      hour.rainProbability === undefined ||
      !Number.isFinite(Number(hour.rainProbability))
    ) {
      throw new Error(
        `Invalid rain probability for ${data.locationName}`
      );
    }

    const probability = Number(hour.rainProbability);

    if (probability < 0 || probability > 100) {
      throw new Error(
        `Rain probability out of range for ${data.locationName}`
      );
    }

    return {
      ...hour,
      rainProbability: probability,
      riskLevel: classifyRisk(probability)
    };

  });

  // ========================================
  // 5. Separate Rain Risk Levels
  // ========================================

  const noneHours = classifiedForecast.filter(
    hour => hour.riskLevel === "NONE"
  );

  const lowHours = classifiedForecast.filter(
    hour => hour.riskLevel === "LOW"
  );

  const moderateHours = classifiedForecast.filter(
    hour => hour.riskLevel === "MODERATE"
  );

  const watchHours = classifiedForecast.filter(
    hour => hour.riskLevel === "WATCH"
  );

  const highRiskHours = classifiedForecast.filter(
    hour => hour.riskLevel === "HIGH"
  );

  // ========================================
  // 6. Prepare Alert-Level Risk Hours
  // ========================================

  // Only WATCH and HIGH are included.
  // These hours will be passed to Time Grouping.

  const riskHours = classifiedForecast.filter(
    hour =>
      hour.riskLevel === "WATCH" ||
      hour.riskLevel === "HIGH"
  );

  // ========================================
  // 7. Calculate Maximum Rain Probability
  // ========================================

  const maxRainProbability = Math.max(
    ...classifiedForecast.map(
      hour => hour.rainProbability
    )
  );

  // Highest rainfall probability of the day
  const overallRainStatus = classifyRisk(
    maxRainProbability
  );

  // ========================================
  // 8. Return Results
  // ========================================

  return {
    json: {
      ...data,

      // Risk thresholds
      noneThreshold: 0,
      moderateThreshold: MODERATE_THRESHOLD,
      watchThreshold: WATCH_THRESHOLD,
      highThreshold: HIGH_THRESHOLD,

      // Overall daily rain status
      maxRainProbability,
      overallRainStatus,

      // Rain potential and alert flags
      hasRainPotential:
        maxRainProbability >= MODERATE_THRESHOLD,

      hasModerateRainChance:
        moderateHours.length > 0,

      hasRainRisk:
        riskHours.length > 0,

      // Hour counts by risk level
      noneHoursCount: noneHours.length,
      lowHoursCount: lowHours.length,
      moderateHoursCount: moderateHours.length,
      watchHoursCount: watchHours.length,
      highRiskHoursCount: highRiskHours.length,

      // Preserve old field names for downstream nodes
      rainyHoursCount: riskHours.length,
      riskHoursCount: riskHours.length,

      // Classified forecast
      classifiedForecast,

      // Separate risk groups
      noneHours,
      lowHours,
      moderateHours,
      watchHours,
      highRiskHours,

      // Used by Time Grouping
      riskHours
    }
  };

});

// รวมชั่วโมงที่มีความเสี่ยงฝน แยกตามพื้นที่และระดับความเสี่ยง

const items = $input.all();

// ประมวลผลแต่ละพื้นที่แยกจากกัน
return items.map(item => {
  const data = item.json;

  // ตรวจสอบข้อมูล Risk Hours
  const hours = Array.isArray(data.riskHours)
    ? [...data.riskHours].sort(
        (a, b) => a.time.localeCompare(b.time)
      )
    : [];

  const groups = [];
  let currentGroup = null;

  for (const hour of hours) {
    // แปลงเวลาเป็น Timestamp ตาม UTC+7
    const startMs = new Date(
      `${hour.time}:00+07:00`
    ).getTime();

    if (!Number.isFinite(startMs)) {
      continue;
    }

    const endMs = startMs + 60 * 60 * 1000;

    const probability = Number(hour.rainProbability);
    const precipitation = Number(hour.precipitation ?? 0);

    // ตรวจสอบว่าชั่วโมงใหม่ต่อเนื่องกับกลุ่มเดิมหรือไม่
    const canMerge =
      currentGroup !== null &&
      currentGroup.riskLevel === hour.riskLevel &&
      currentGroup.endMs === startMs;

    if (canMerge) {
      currentGroup.endMs = endMs;

      currentGroup.maxProbability = Math.max(
        currentGroup.maxProbability,
        probability
      );

      currentGroup.minProbability = Math.min(
        currentGroup.minProbability,
        probability
      );

      currentGroup.hoursCount++;
      currentGroup.totalPrecipitation += precipitation;

    } else {
      currentGroup = {
        riskLevel: hour.riskLevel,
        startMs,
        endMs,
        minProbability: probability,
        maxProbability: probability,
        hoursCount: 1,
        totalPrecipitation: precipitation
      };

      groups.push(currentGroup);
    }
  }

  // แปลงเวลาเป็น HH:mm ตามเวลาไทย
  function formatTime(ms) {
    return new Intl.DateTimeFormat("en-GB", {
      timeZone: "Asia/Bangkok",
      hour: "2-digit",
      minute: "2-digit",
      hourCycle: "h23"
    }).format(new Date(ms));
  }

  // สร้างช่วงเวลาเสี่ยงฝน
  const riskPeriods = groups.map(group => ({
    riskLevel: group.riskLevel,
    startTime: formatTime(group.startMs),
    endTime: formatTime(group.endMs),

    minProbability: group.minProbability,
    maxProbability: group.maxProbability,

    hoursCount: group.hoursCount,

    totalPrecipitation: Number(
      group.totalPrecipitation.toFixed(1)
    )
  }));

  // ส่งข้อมูลเดิมทั้งหมดพร้อมผล Time Grouping
  return {
    json: {
      ...data,

      totalPeriods: riskPeriods.length,
      riskPeriods
    }
  };
});

// วิเคราะห์ช่วงเวลาที่คาดว่าจะมีปริมาณฝน แยกตามพื้นที่

const items = $input.all();

return items.map(item => {
  const data = item.json;

  // อ่านข้อมูลพยากรณ์ของพื้นที่ปัจจุบัน
  const forecast = Array.isArray(data.forecast)
    ? data.forecast
    : [];

  // เลือกเฉพาะชั่วโมงที่คาดว่าจะมีปริมาณฝนมากกว่า 0 mm
  const rainyHours = forecast
    .filter(hour =>
      hour.time &&
      Number.isFinite(Number(hour.precipitation)) &&
      Number(hour.precipitation) > 0
    )
    .sort((a, b) => a.time.localeCompare(b.time));

  const rainfallPeriods = [];
  let currentPeriod = null;

  for (const hour of rainyHours) {
    const startMs = new Date(
      `${hour.time}:00+07:00`
    ).getTime();

    if (!Number.isFinite(startMs)) {
      continue;
    }

    const endMs = startMs + 60 * 60 * 1000;
    const precipitation = Number(hour.precipitation);

    // รวมเฉพาะชั่วโมงที่ต่อเนื่องกัน
    const canMerge =
      currentPeriod !== null &&
      currentPeriod.endMs === startMs;

    if (canMerge) {
      currentPeriod.endMs = endMs;
      currentPeriod.hoursCount++;
      currentPeriod.totalPrecipitation += precipitation;
    } else {
      currentPeriod = {
        startMs,
        endMs,
        hoursCount: 1,
        totalPrecipitation: precipitation
      };

      rainfallPeriods.push(currentPeriod);
    }
  }

  // แปลงเวลาเป็น HH:mm ตามเวลาไทย
  function formatTime(ms) {
    return new Intl.DateTimeFormat("en-GB", {
      timeZone: "Asia/Bangkok",
      hour: "2-digit",
      minute: "2-digit",
      hourCycle: "h23"
    }).format(new Date(ms));
  }

  // สรุปช่วงเวลาที่คาดว่าจะมีฝน
  const periods = rainfallPeriods.map(period => ({
    startTime: formatTime(period.startMs),
    endTime: formatTime(period.endMs),
    hoursCount: period.hoursCount,
    totalPrecipitation: Number(
      period.totalPrecipitation.toFixed(1)
    )
  }));

  // รักษาข้อมูลเดิมและเพิ่มผล Rainfall Analysis
  return {
    json: {
      ...data,
      totalRainfallPeriods: periods.length,
      rainfallPeriods: periods
    }
  };
});

/*
 * Filter Upcoming Periods
 * Weather Alert Bot - Multi Location
 *
 * Purpose:
 * 1. Filter past forecast hours.
 * 2. Keep current and future forecast hours.
 * 3. Filter expired risk periods.
 * 4. Filter expired rainfall periods.
 * 5. Filter expired moderate hours.
 * 6. Preserve all original data.
 *
 * Timezone: Asia/Bangkok
 */

// ==========================================
// 1. Get Input
// ==========================================

const items = $input.all();

if (items.length === 0) {
  throw new Error("No location data received");
}

// Current time
const now = new Date();
const nowMs = now.getTime();

// ==========================================
// 2. Get Thailand Date and Time
// ==========================================

const thaiDate = new Intl.DateTimeFormat("en-CA", {
  timeZone: "Asia/Bangkok",
  year: "numeric",
  month: "2-digit",
  day: "2-digit"
}).format(now);

const thaiTime = new Intl.DateTimeFormat("en-GB", {
  timeZone: "Asia/Bangkok",
  hour: "2-digit",
  minute: "2-digit",
  hourCycle: "h23"
}).format(now);

// ==========================================
// 3. Time Conversion Functions
// ==========================================

// Convert Thailand date and HH:mm to timestamp
function toBangkokTimestamp(date, time) {

  if (
    typeof date !== "string" ||
    !/^\d{4}-\d{2}-\d{2}$/.test(date) ||
    typeof time !== "string" ||
    !/^([01]\d|2[0-3]):[0-5]\d$/.test(time)
  ) {
    return NaN;
  }

  return new Date(
    `${date}T${time}:00+07:00`
  ).getTime();
}

// Convert forecast ISO time to timestamp
function toForecastTimestamp(time) {

  if (
    typeof time !== "string" ||
    !/^\d{4}-\d{2}-\d{2}T([01]\d|2[0-3]):[0-5]\d$/.test(time)
  ) {
    return NaN;
  }

  return new Date(
    `${time}:00+07:00`
  ).getTime();
}

// ==========================================
// 4. Filter Upcoming Periods
// ==========================================

function filterUpcoming(periods, date, locationName, fieldName) {

  if (!Array.isArray(periods)) {
    throw new Error(
      `Invalid ${fieldName} for ${locationName}`
    );
  }

  return periods
    .map(period => {

      if (!period || !period.startTime || !period.endTime) {
        throw new Error(
          `Invalid period data in ${fieldName} for ${locationName}`
        );
      }

      const startMs = toBangkokTimestamp(
        date,
        period.startTime
      );

      let endMs = toBangkokTimestamp(
        date,
        period.endTime
      );

      if (
        !Number.isFinite(startMs) ||
        !Number.isFinite(endMs)
      ) {
        throw new Error(
          `Invalid period time in ${fieldName} for ${locationName}`
        );
      }

      // Support periods ending after midnight
      if (endMs <= startMs) {
        endMs += 24 * 60 * 60 * 1000;
      }

      const isOngoing =
        startMs <= nowMs &&
        endMs > nowMs;

      return {
        ...period,

        displayStartTime: isOngoing
          ? thaiTime
          : period.startTime,

        isOngoing,

        _endMs: endMs
      };

    })

    // Keep only periods that have not ended
    .filter(period => period._endMs > nowMs)

    // Remove internal timestamp
    .map(({ _endMs, ...period }) => period);
}

// ==========================================
// 5. Filter Upcoming Moderate Hours
// ==========================================

function filterUpcomingModerate(hours, locationName) {

  if (!Array.isArray(hours)) {
    throw new Error(
      `Invalid moderateHours for ${locationName}`
    );
  }

  return hours.filter(hour => {

    if (!hour || !hour.time) {
      throw new Error(
        `Invalid moderate hour for ${locationName}`
      );
    }

    const startMs = toForecastTimestamp(hour.time);

    if (!Number.isFinite(startMs)) {
      throw new Error(
        `Invalid moderate forecast time for ${locationName}`
      );
    }

    const endMs =
      startMs + 60 * 60 * 1000;

    // Keep current and future hours
    return endMs > nowMs;

  });
}

// ==========================================
// 6. Process Each Location
// ==========================================

return items.map((item, index) => {

  const data = item.json;

  const locationName =
    data.locationName || `Location ${index + 1}`;

  // ----------------------------------------
  // 6.1 Validate Location Data
  // ----------------------------------------

  if (!data.locationId || !data.locationName) {
    throw new Error(
      `Missing location information at item ${index}`
    );
  }

  if (
    typeof data.date !== "string" ||
    !/^\d{4}-\d{2}-\d{2}$/.test(data.date)
  ) {
    throw new Error(
      `Invalid forecast date for ${locationName}`
    );
  }

  // ----------------------------------------
  // 6.2 Validate Forecast
  // ----------------------------------------

  if (!Array.isArray(data.forecast)) {
    throw new Error(
      `Invalid forecast data for ${locationName}`
    );
  }

  // ----------------------------------------
  // 6.3 Filter Upcoming Forecast
  // ----------------------------------------

  const upcomingForecast = data.forecast.filter(hour => {

    if (!hour || !hour.time) {
      throw new Error(
        `Invalid forecast hour for ${locationName}`
      );
    }

    const forecastStartMs = toForecastTimestamp(
      hour.time
    );

    if (!Number.isFinite(forecastStartMs)) {
      throw new Error(
        `Invalid forecast timestamp for ${locationName}`
      );
    }

    const forecastEndMs =
      forecastStartMs + 60 * 60 * 1000;

    // Keep current and future forecast hours
    return forecastEndMs > nowMs;

  });

  // ----------------------------------------
  // 6.4 Filter Upcoming Risk Periods
  // ----------------------------------------

  const upcomingRiskPeriods = filterUpcoming(
    data.riskPeriods,
    data.date,
    locationName,
    "riskPeriods"
  );

  // ----------------------------------------
  // 6.5 Filter Upcoming Rainfall Periods
  // ----------------------------------------

  const upcomingRainfallPeriods = filterUpcoming(
    data.rainfallPeriods,
    data.date,
    locationName,
    "rainfallPeriods"
  );

  // ----------------------------------------
  // 6.6 Filter Upcoming Moderate Hours
  // ----------------------------------------

  const upcomingModerateHours = filterUpcomingModerate(
    data.moderateHours,
    locationName
  );

  // ----------------------------------------
  // 6.7 Calculate Upcoming Status
  // ----------------------------------------

  const hasUpcomingRainRisk =
    upcomingRiskPeriods.length > 0;

  const hasUpcomingModerateChance =
    upcomingModerateHours.length > 0;

  // Show rain alert section only for WATCH/HIGH
  const showRainSection =
    hasUpcomingRainRisk;

  // ========================================
  // 7. Return Processed Data
  // ========================================

  return {
    json: {

      // Preserve all original data
      ...data,

      // Processing timestamp
      processedAt: `${thaiDate}T${thaiTime}`,

      // Upcoming forecast
      upcomingForecast,

      // Upcoming risk periods (WATCH/HIGH)
      upcomingRiskPeriods,

      // Upcoming rainfall periods
      upcomingRainfallPeriods,

      // Upcoming moderate hours
      upcomingModerateHours,

      // Upcoming status
      hasUpcomingRainRisk,
      hasUpcomingModerateChance,

      // Alert visibility
      showRainSection

    }
  };

});

/*
 * Daily Summary Message - Compact Pattern A FINAL
 * Weather Alert Bot - Multi Location
 *
 * Business Rules:
 * NONE     = 0%
 * LOW      = 1-29%
 * MODERATE = 30-59%
 * WATCH    = 60-69%
 * HIGH     = 70-100%
 *
 * Notification Policy:
 * - HIGH: Show risk period, probability and precipitation.
 * - WATCH: Show monitoring period, probability and precipitation.
 * - LOW / MODERATE: Brief summary only.
 * - NONE: Show no-rain-probability message.
 * - No separator lines between locations.
 * - One LINE message for all locations.
 */

// ==========================================
// 1. Configuration
// ==========================================

const REQUIRED_LOCATIONS = ["salaya", "nongkhaem"];

const MODERATE_THRESHOLD = 30;
const WATCH_THRESHOLD = 60;
const HIGH_THRESHOLD = 70;

const locationOrder = {
  salaya: 1,
  nongkhaem: 2
};

// ==========================================
// 2. Get and Validate Input
// ==========================================

const items = $input.all();

if (items.length === 0) {
  throw new Error("No weather data received");
}

const locations = items
  .map(item => item.json)
  .sort((a, b) =>
    (locationOrder[a.locationId] ?? 99) -
    (locationOrder[b.locationId] ?? 99)
  );

// Validate location count
if (locations.length !== REQUIRED_LOCATIONS.length) {
  throw new Error(
    `Expected ${REQUIRED_LOCATIONS.length} locations, received ${locations.length}`
  );
}

// Validate required location IDs
const receivedIds = locations.map(
  data => data.locationId
);

for (const id of REQUIRED_LOCATIONS) {
  if (!receivedIds.includes(id)) {
    throw new Error(`Missing location: ${id}`);
  }
}

// Prevent duplicate locations
if (new Set(receivedIds).size !== receivedIds.length) {
  throw new Error("Duplicate location detected");
}

// ==========================================
// 3. Validate Location Data
// ==========================================

for (const data of locations) {

  if (
    !data.locationName ||
    !data.date ||
    !data.dailyAnalysis
  ) {
    throw new Error(
      `Incomplete weather data for ${data.locationId}`
    );
  }

  if (
    !Array.isArray(data.upcomingForecast) ||
    !Array.isArray(data.upcomingRiskPeriods) ||
    !Array.isArray(data.upcomingModerateHours) ||
    !Array.isArray(data.upcomingRainfallPeriods)
  ) {
    throw new Error(
      `Missing forecast or rain analysis data for ${data.locationId}`
    );
  }
}

// Validate matching forecast dates
const dates = [
  ...new Set(locations.map(data => data.date))
];

if (
  dates.length !== 1 ||
  !/^\d{4}-\d{2}-\d{2}$/.test(dates[0])
) {
  throw new Error(
    "Forecast dates are invalid or do not match"
  );
}

// ==========================================
// 4. Format Date and Numbers
// ==========================================

const [year, month, day] = dates[0]
  .split("-")
  .map(Number);

const monthNames = [
  "ม.ค.", "ก.พ.", "มี.ค.", "เม.ย.",
  "พ.ค.", "มิ.ย.", "ก.ค.", "ส.ค.",
  "ก.ย.", "ต.ค.", "พ.ย.", "ธ.ค."
];

if (
  !Number.isInteger(year) ||
  !Number.isInteger(month) ||
  !Number.isInteger(day) ||
  month < 1 ||
  month > 12 ||
  day < 1 ||
  day > 31
) {
  throw new Error("Invalid forecast date");
}

const thaiDate =
  `${day} ${monthNames[month - 1]} ${year + 543}`;

function formatNumber(value) {

  if (
    value === null ||
    value === undefined ||
    value === ""
  ) {
    return "ไม่ระบุ";
  }

  const number = Number(value);

  if (!Number.isFinite(number)) {
    return "ไม่ระบุ";
  }

  return Number.isInteger(number)
    ? String(number)
    : number.toFixed(1);
}

function formatTemperature(value) {

  const formatted = formatNumber(value);

  return formatted === "ไม่ระบุ"
    ? formatted
    : `${formatted}°C`;
}

// ==========================================
// 5. Rain Classification V2
// ==========================================

function classifyRainRisk(probability) {

  if (probability === 0) {
    return "NONE";
  }

  if (probability < MODERATE_THRESHOLD) {
    return "LOW";
  }

  if (probability < WATCH_THRESHOLD) {
    return "MODERATE";
  }

  if (probability < HIGH_THRESHOLD) {
    return "WATCH";
  }

  return "HIGH";
}

const statusMessages = {
  NONE: "ไม่พบโอกาสเกิดฝนจากแบบจำลอง",
  LOW: "โอกาสเกิดฝนต่ำ",
  MODERATE: "มีโอกาสเกิดฝนปานกลาง"
};

// ==========================================
// 6. Analyze Upcoming Rain Forecast
// ==========================================

function analyzeRainStatus(forecast, locationName) {

  if (forecast.length === 0) {
    return {
      available: false,
      maxProbability: null,
      maxProbabilityTime: null,
      riskLevel: null,
      statusText: "ไม่มีข้อมูลพยากรณ์ฝน"
    };
  }

  const validHours = forecast.map(hour => {

    if (
      !hour ||
      typeof hour.time !== "string" ||
      hour.rainProbability === null ||
      hour.rainProbability === undefined
    ) {
      throw new Error(
        `Invalid rainfall forecast for ${locationName}`
      );
    }

    const probability = Number(
      hour.rainProbability
    );

    if (
      !Number.isFinite(probability) ||
      probability < 0 ||
      probability > 100
    ) {
      throw new Error(
        `Invalid rain probability for ${locationName}`
      );
    }

    return {
      ...hour,
      rainProbability: probability
    };
  });

  // Find highest probability in remaining forecast
  const maxHour = validHours.reduce((max, hour) =>
    hour.rainProbability > max.rainProbability
      ? hour
      : max
  );

  const maxProbability = maxHour.rainProbability;

  const riskLevel = classifyRainRisk(
    maxProbability
  );

  return {
    available: true,
    maxProbability,
    maxProbabilityTime: maxHour.time.slice(11, 16),
    riskLevel,
    statusText:
      statusMessages[riskLevel] || riskLevel
  };
}

// ==========================================
// 7. Validate Risk Periods
// ==========================================

function prepareRiskPeriods(periods, locationName) {

  if (!Array.isArray(periods)) {
    throw new Error(
      `Invalid risk periods for ${locationName}`
    );
  }

  // Validate all periods before sorting
  const validatedPeriods = periods.map(period => {

    if (
      !period ||
      !["WATCH", "HIGH"].includes(period.riskLevel) ||
      !/^([01]\d|2[0-3]):[0-5]\d$/.test(period.startTime || "") ||
      !/^([01]\d|2[0-3]):[0-5]\d$/.test(period.endTime || "")
    ) {
      throw new Error(
        `Invalid risk period for ${locationName}`
      );
    }

    const minProbability = Number(
      period.minProbability
    );

    const maxProbability = Number(
      period.maxProbability
    );

    if (
      !Number.isFinite(minProbability) ||
      !Number.isFinite(maxProbability) ||
      minProbability < 0 ||
      maxProbability > 100 ||
      minProbability > maxProbability
    ) {
      throw new Error(
        `Invalid probability range for ${locationName}`
      );
    }

    // HIGH must be 70-100%
    if (
      period.riskLevel === "HIGH" &&
      minProbability < HIGH_THRESHOLD
    ) {
      throw new Error(
        `HIGH threshold mismatch for ${locationName}`
      );
    }

    // WATCH must be 60-69%
    if (
      period.riskLevel === "WATCH" &&
      (
        minProbability < WATCH_THRESHOLD ||
        maxProbability >= HIGH_THRESHOLD
      )
    ) {
      throw new Error(
        `WATCH threshold mismatch for ${locationName}`
      );
    }

    // Validate accumulated precipitation
    const precipitation =
      period.totalPrecipitation === null ||
      period.totalPrecipitation === undefined
        ? null
        : Number(period.totalPrecipitation);

    if (
      precipitation !== null &&
      (
        !Number.isFinite(precipitation) ||
        precipitation < 0
      )
    ) {
      throw new Error(
        `Invalid precipitation for ${locationName}`
      );
    }

    return {
      ...period,
      minProbability,
      maxProbability,
      totalPrecipitation: precipitation
    };
  });

  return validatedPeriods.sort((a, b) =>
    a.startTime.localeCompare(b.startTime)
  );
}

// ==========================================
// 8. Prepare Daily Summary
// ==========================================

const lines = [
  "🌤️ Weather Alert — Daily Summary",
  `📅 ${thaiDate}`,
  ""
];

const locationResults = [];

let hasAnyRainRisk = false;
let hasCompleteRainForecast = true;

// ==========================================
// 9. Build Each Location Report
// ==========================================

for (const data of locations) {

  const daily = data.dailyAnalysis;
  const locationName = data.locationName;

  // ----------------------------------------
  // 9.1 Analyze Remaining Rain Forecast
  // ----------------------------------------

  const rainStatus = analyzeRainStatus(
    data.upcomingForecast,
    locationName
  );

  if (!rainStatus.available) {
    hasCompleteRainForecast = false;
  }

  // ----------------------------------------
  // 9.2 Prepare WATCH / HIGH Periods
  // ----------------------------------------

  const riskPeriods = prepareRiskPeriods(
    data.upcomingRiskPeriods,
    locationName
  );

  const hasRainAlert =
    riskPeriods.length > 0;

  // ----------------------------------------
  // 9.3 Cross-check Forecast and Risk Periods
  // ----------------------------------------

  if (rainStatus.available) {

    const forecastHasRisk =
      rainStatus.maxProbability >= WATCH_THRESHOLD;

    if (forecastHasRisk !== hasRainAlert) {
      throw new Error(
        `Forecast and risk periods do not match for ${locationName}`
      );
    }

  } else if (hasRainAlert) {

    throw new Error(
      `Risk periods exist but forecast is unavailable for ${locationName}`
    );
  }

  // Validate upstream risk flag
  if (
    typeof data.hasUpcomingRainRisk === "boolean" &&
    data.hasUpcomingRainRisk !== hasRainAlert
  ) {
    throw new Error(
      `Upcoming rain risk flag mismatch for ${locationName}`
    );
  }

  if (hasRainAlert) {
    hasAnyRainRisk = true;
  }

  // ----------------------------------------
  // 9.4 Location Heading
  // ----------------------------------------

  lines.push(
    `📍 ${locationName}`
  );

  // ----------------------------------------
  // 9.5 Temperature Summary
  // ----------------------------------------

  lines.push(
    `🌡️ สูงสุด ${formatTemperature(daily.maxTemperature)} (${daily.maxTemperatureTime || "ไม่ระบุ"}) | ต่ำสุด ${formatTemperature(daily.minTemperature)} (${daily.minTemperatureTime || "ไม่ระบุ"})`,
    `🥵 รู้สึกเหมือนสูงสุด ${formatTemperature(daily.maxFeelsLike)}`
  );

  lines.push("");

  // ----------------------------------------
  // 9.6 LOW / MODERATE / NONE Summary
  // ----------------------------------------

  if (!rainStatus.available) {

    lines.push(
      "⚪ ไม่มีข้อมูลพยากรณ์ฝนสำหรับช่วงเวลาที่เหลือ"
    );

  } else if (rainStatus.riskLevel === "HIGH") {

    // HIGH details displayed in risk period section.

  } else if (rainStatus.riskLevel === "WATCH") {

    // WATCH details displayed in risk period section.

  } else if (rainStatus.riskLevel === "MODERATE") {

    lines.push(
      `🟡 ${statusMessages.MODERATE} (สูงสุด ${rainStatus.maxProbability}%)`
    );

  } else if (rainStatus.riskLevel === "LOW") {

    lines.push(
      `🟢 ${statusMessages.LOW} (สูงสุด ${rainStatus.maxProbability}%)`
    );

  } else {

    lines.push(
      `✅ ${statusMessages.NONE}`
    );
  }

  // ----------------------------------------
  // 9.7 Display HIGH / WATCH Periods
  // ----------------------------------------

  if (hasRainAlert) {

    for (const period of riskPeriods) {

      const start =
        period.displayStartTime || period.startTime;

      const end = period.endTime;

      // Separate HIGH and WATCH wording
      const periodHeading =
        period.riskLevel === "HIGH"
          ? `🔴 HIGH | ช่วงเสี่ยงฝนสูง: ${start}–${end} น.`
          : `🟠 WATCH | ช่วงที่ควรเฝ้าระวังฝน: ${start}–${end} น.`;

      // Risk level and specific time
      lines.push(
        "",
        periodHeading
      );

      // Probability for this specific period
      lines.push(
        `โอกาสเกิดฝน: ${period.minProbability}–${period.maxProbability}%`
      );

      // Accumulated precipitation for this period
      lines.push(
        `ปริมาณฝนคาดการณ์สะสม: ${
          period.totalPrecipitation === null
            ? "ไม่มีข้อมูล"
            : `${formatNumber(period.totalPrecipitation)} mm`
        }`
      );

      // Currently ongoing period
      if (period.isOngoing) {
        lines.push(
          "ช่วงเวลาดังกล่าวกำลังดำเนินอยู่"
        );
      }
    }
  }

  // ----------------------------------------
  // 9.8 Preserve Detailed Data for QA
  // ----------------------------------------

  locationResults.push({

    locationId: data.locationId,
    locationName,

    dailyAnalysis: daily,

    rainStatus,

    hasUpcomingRainRisk: hasRainAlert,

    upcomingRiskPeriods: riskPeriods,

    upcomingModerateHours:
      data.upcomingModerateHours,

    upcomingRainfallPeriods:
      data.upcomingRainfallPeriods,

    moderateHoursCount:
      data.upcomingModerateHours.length,

    rainfallPeriodsCount:
      data.upcomingRainfallPeriods.length
  });

  // Blank lines between locations
  lines.push("", "");
}

// ==========================================
